// Block (composition) — a task checklist paired with aggregate completion progress.
// Stack owns arrangement; Checkbox owns task interaction and ProgressBar owns progress representation.
import type { Ref } from "react";
import { Checkbox } from "../components/Checkbox";
import { ProgressBar } from "../components/ProgressBar";
import { Stack } from "../layouts/Stack";
import "./TaskChecklist.css";

export interface TaskChecklistProps {
  tasks: { id: string; label: string; done?: boolean }[];
  onToggle?: (id: string, done: boolean) => void;
  heading?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function TaskChecklist({
  tasks,
  onToggle,
  heading,
  className,
  ref,
}: TaskChecklistProps) {
  const completed = tasks.filter((task) => task.done).length;
  const progress = tasks.length > 0 ? (completed / tasks.length) * 100 : 0;

  return (
    <Stack
      as="section"
      ref={ref}
      gap="small"
      aria-label={heading ?? "Task checklist"}
      className={className ? `sd-taskchecklist ${className}` : "sd-taskchecklist"}
    >
      {heading && (
        <>
          <h2 className="sd-taskchecklist__heading sd-type-title-medium">{heading}</h2>
        </>
      )}
      {/* "3 of 5 complete" is the bar's VALUE, not its name — so it goes to `valueLabel`, which
          drives both the visible value and `aria-valuetext`. Putting it in `label` made the
          visible text a label the accessible name ("Progress") did not contain. The section's
          own heading already names this region, so the bar stays visually label-less. */}
      <ProgressBar
        value={progress}
        showValue
        aria-label="Progress"
        valueLabel={`${completed} of ${tasks.length} complete`}
      />
      {/* spacing: attachment — the progress line heads the tasks it counts */}
      <Stack gap="small" className="sd-taskchecklist__tasks">
        {tasks.map((task) => (
          <Checkbox
            key={task.id}
            isSelected={Boolean(task.done)}
            onChange={(done) => onToggle?.(task.id, done)}
          >
            {task.label}
          </Checkbox>
        ))}
      </Stack>
    </Stack>
  );
}
